1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		planID      string
20		terms       PlanTerms
21		activatedAt time.Time
22		// termsHistory 按生效月份升序记录每次换套餐后的条件；
23		// 首条为开通当月适用的开通快照。账单按账期从中取当时适用的条件。
24		termsHistory []termsEntry
25		// pending 尚未生效的换套餐安排，每账户至多一条；nil 表示无安排。
26		pending *PlanChange
27	}
28	
29	type eventRecord struct {
30		at     time.Time
31		qty    int64
32		period Month
33	}
34	
35	type billRecord struct {
36		bill Bill
37	}
38	
39	type paymentRecord struct {
40		period Month
41		amount int64
42	}
43	
44	type account struct {
45		id       string
46		sub      *subRecord
47		events   map[string]eventRecord
48		usage    map[Month]int64
49		bills    map[Month]*billRecord
50		payments map[string]paymentRecord
51	}
52	
53	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
54	func NewService() *Service {
55		return NewServiceWithClock(time.Now)
56	}
57	
58	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
59	func NewServiceWithClock(now func() time.Time) *Service {
60		if now == nil {
61			now = time.Now
62		}
63		return &Service{
64			now:      now,
65			accounts: make(map[string]*account),
66			plans:    make(map[string]Plan),
67		}
68	}
69	
70	func (s *Service) nowUTC() time.Time {
71		return s.now().UTC()
72	}
73	
74	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
75	func (s *Service) CreateAccount(id string) error {
76		if id == "" {
77			return invalidf("account id is empty")
78		}
79		s.mu.Lock()
80		defer s.mu.Unlock()
81		if _, ok := s.accounts[id]; ok {
82			return ErrAccountExists
83		}
84		s.accounts[id] = &account{
85			id:       id,
86			events:   make(map[string]eventRecord),
87			usage:    make(map[Month]int64),
88			bills:    make(map[Month]*billRecord),
89			payments: make(map[string]paymentRecord),
90		}
91		return nil
92	}
93	
94	func validatePlan(p Plan) error {
95		if p.ID == "" {
96			return invalidf("plan id is empty")
97		}
98		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
99			return invalidf("plan %q has negative amount or quantity", p.ID)
100		}
101		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
102			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
103		}
104		return nil
105	}
106	
107	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
108	func (s *Service) CreatePlan(p Plan) error {
109		if err := validatePlan(p); err != nil {
110			return err
111		}
112		s.mu.Lock()
113		defer s.mu.Unlock()
114		if _, ok := s.plans[p.ID]; ok {
115			return ErrPlanExists
116		}
117		s.plans[p.ID] = p
118		return nil
119	}
120	
121	// UpdatePlan 更新套餐当前条件。只影响之后开通的订阅，
122	// 已开通订阅继续使用开通时保存的快照。
123	func (s *Service) UpdatePlan(p Plan) error {
124		if err := validatePlan(p); err != nil {
125			return err
126		}
127		s.mu.Lock()
128		defer s.mu.Unlock()
129		if _, ok := s.plans[p.ID]; !ok {
130			return ErrPlanNotFound
131		}
132		s.plans[p.ID] = p
133		return nil
134	}
135	
136	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
137	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
138	// 首月仍收完整月费并提供完整额度。
139	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
140		if accountID == "" {
141			return invalidf("account id is empty")
142		}
143		if planID == "" {
144			return invalidf("plan id is empty")
145		}
146		if activatedAt.IsZero() {
147			return invalidf("activated at is zero")
148		}
149		s.mu.Lock()
150		defer s.mu.Unlock()
151		acc, ok := s.accounts[accountID]
152		if !ok {
153			return ErrAccountNotFound
154		}
155		plan, ok := s.plans[planID]
156		if !ok {
157			return ErrPlanNotFound
158		}
159		if acc.sub != nil {
160			return ErrSubscriptionExists
161		}
162		acc.sub = &subRecord{
163			planID:      planID,
164			terms:       termsOf(plan),
165			activatedAt: activatedAt.UTC(),
166			termsHistory: []termsEntry{{
167				effective: MonthOf(activatedAt),
168				terms:     termsOf(plan),
169			}},
170		}
171		return nil
172	}
173	
174	// nextMonth 返回 period 的下一个 UTC 自然月。
175	func nextMonth(period Month) Month {
176		return MonthOf(period.End())
177	}
178	
179	// applyDueChangesLocked 把已到生效月份月初零点的待生效安排落入条件历史。
180	// 到达月初零点即生效，无需先上报用量或生成账单；即使中间若干月没有调用服务，
181	// 再次进入时也会在此一次性补齐，当前条件仍正确。调用时持有 s.mu。
182	func (s *Service) applyDueChangesLocked(acc *account, now time.Time) {
183		sub := acc.sub
184		if sub == nil {
185			return
186		}
187		current := MonthOf(now)
188		for sub.pending != nil && !current.Before(sub.pending.EffectivePeriod) {
189			entry := termsEntry{
190				effective: sub.pending.EffectivePeriod,
191				terms:     sub.pending.Terms,
192			}
193			sub.termsHistory = append(sub.termsHistory, entry)
194			sub.planID = sub.pending.TargetPlanID
195			sub.terms = sub.pending.Terms
196			sub.pending = nil
197		}
198	}
199	
200	// termsForPeriodLocked 返回指定账期当时适用的套餐条件快照。
201	// 条件历史按生效月份升序，取不晚于 period 的最后一条；
202	// 这样历史账单始终按该账期条件计算，不受后续换套餐影响。调用时持有 s.mu。
203	func termsForPeriodLocked(sub *subRecord, period Month) PlanTerms {
204		t := sub.termsHistory[0].terms
205		for _, e := range sub.termsHistory {
206			if period.Before(e.effective) {
207				break
208			}
209			t = e.terms
210		}
211		return t
212	}
213	
214	// SchedulePlanChange 安排账户从下一个 UTC 自然月起改用另一套餐，升级与降级规则相同。
215	//
216	// 成功时返回目标套餐在本次安排时的完整计费条件快照与生效账期（请求被接受时的
217	// 下一个 UTC 自然月），之后修改套餐定义不影响本安排。当前月仍按旧套餐收取完整
218	// 月费并提供完整额度，不按天补差，也不迁移本月已发生的用量。
219	//
220	// 每个账户至多保留一条尚未生效的安排：再次安排同一目标套餐时返回原安排，
221	// 不重新取价（Created 为 false）；安排另一目标套餐则替换原安排，生效月份仍为
222	// 本次请求被接受时的下一月。欠费停用期间也可以安排。
223	//
224	// 账户不存在、尚未开通订阅、开通时刻尚未到达、目标套餐不存在、目标套餐与当前
225	// 生效套餐相同时请求失败，原有安排保持不变。
226	func (s *Service) SchedulePlanChange(accountID, targetPlanID string) (PlanChangeResult, error) {
227		if accountID == "" {
228			return PlanChangeResult{}, invalidf("account id is empty")
229		}
230		if targetPlanID == "" {
231			return PlanChangeResult{}, invalidf("target plan id is empty")
232		}
233		s.mu.Lock()
234		defer s.mu.Unlock()
235	
236		acc, ok := s.accounts[accountID]
237		if !ok {
238			return PlanChangeResult{}, ErrAccountNotFound
239		}
240		if acc.sub == nil {
241			return PlanChangeResult{}, ErrSubscriptionNotFound
242		}
243		now := s.nowUTC()
244		if now.Before(acc.sub.activatedAt) {
245			return PlanChangeResult{}, ErrSubscriptionNotActivated
246		}
247		// 先让已到期的安排生效：例如跨月后的首次调用，此时“当前套餐”已是新套餐。
248		s.applyDueChangesLocked(acc, now)
249	
250		plan, ok := s.plans[targetPlanID]
251		if !ok {
252			return PlanChangeResult{}, ErrPlanNotFound
253		}
254		if targetPlanID == acc.sub.planID {
255			return PlanChangeResult{}, ErrPlanChangeSamePlan
256		}
257	
258		// 已有安排且目标相同：原样返回，不重新取价。
259		if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
260			return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
261		}
262	
263		change := PlanChange{
264			TargetPlanID:    targetPlanID,
265			Terms:           termsOf(plan),
266			EffectivePeriod: nextMonth(MonthOf(now)),
267		}
268		acc.sub.pending = &change
269		return PlanChangeResult{Created: true, Change: change}, nil
270	}
271	
272	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
273	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
274	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
275	// 账户不存在或尚未开通订阅时失败。
276	func (s *Service) CancelPlanChange(accountID string) error {
277		if accountID == "" {
278			return invalidf("account id is empty")
279		}
280		s.mu.Lock()
281		defer s.mu.Unlock()
282		acc, ok := s.accounts[accountID]
283		if !ok {
284			return ErrAccountNotFound
285		}
286		if acc.sub == nil {
287			return ErrSubscriptionNotFound
288		}
289		// 已到生效月份月初零点的安排视为已生效，不可撤回。
290		s.applyDueChangesLocked(acc, s.nowUTC())
291		acc.sub.pending = nil
292		return nil
293	}
294	
295	// RecordEvent 上报一条用量事件。
296	//
297	// 事件按发生时刻归入 UTC 自然月账期；早于订阅开通或晚于当前时刻的事件被拒绝。
298	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计，
299	// 相同标识但时刻或数量不同返回 ErrEventConflict。
300	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新事件；
301	// 但此前已接收事件的完全相同重报始终成功。
302	func (s *Service) RecordEvent(e Event) (EventResult, error) {
303		if e.AccountID == "" {
304			return EventResult{}, invalidf("account id is empty")
305		}
306		if e.EventID == "" {
307			return EventResult{}, invalidf("event id is empty")
308		}
309		if e.Quantity < 0 {
310			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
311		}
312		if e.At.IsZero() {
313			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
314		}
315		at := e.At.UTC()
316	
317		s.mu.Lock()
318		defer s.mu.Unlock()
319	
320		acc, ok := s.accounts[e.AccountID]
321		if !ok {
322			return EventResult{}, ErrAccountNotFound
323		}
324		if acc.sub == nil {
325			return EventResult{}, ErrSubscriptionNotFound
326		}
327	
328		// 进入即补齐已到期的换套餐安排，保证并发下各操作观察到一致的当前套餐。
329		s.applyDueChangesLocked(acc, s.nowUTC())
330	
331		// 去重优先：完全相同的重报即使发生在出账后或停用期间也返回成功。
332		if prev, ok := acc.events[e.EventID]; ok {
333			if !prev.at.Equal(at) || prev.qty != e.Quantity {
334				return EventResult{}, ErrEventConflict
335			}
336			return EventResult{Accepted: false, Period: prev.period}, nil
337		}
338	
339		if at.Before(acc.sub.activatedAt) {
340			return EventResult{}, ErrEventBeforeSubscription
341		}
342		now := s.nowUTC()
343		if at.After(now) {
344			return EventResult{}, ErrEventInFuture
345		}
346	
347		period := MonthOf(at)
348		if _, billed := acc.bills[period]; billed {
349			return EventResult{}, ErrMonthBilled
350		}
351		if s.isSuspendedLocked(acc, now) {
352			return EventResult{}, ErrSuspended
353		}
354	
355		total, ok := addNonNeg(acc.usage[period], e.Quantity)
356		if !ok {
357			return EventResult{}, ErrOverflow
358		}
359		// 所有校验通过后才落库：失败不消耗事件标识。
360		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
361		acc.usage[period] = total
362		return EventResult{Accepted: true, Period: period}, nil
363	}
364	
365	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
366	// 只能为开通当月及以后、且已经结束的月份生成账单。
367	// 重复调用得到同一账单；出账后金额与用量明细固定。
368	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
369		if accountID == "" {
370			return Bill{}, invalidf("account id is empty")
371		}
372		if period.Month < time.January || period.Month > time.December {
373			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
374		}
375		s.mu.Lock()
376		defer s.mu.Unlock()
377	
378		acc, ok := s.accounts[accountID]
379		if !ok {
380			return Bill{}, ErrAccountNotFound
381		}
382		if acc.sub == nil {
383			return Bill{}, ErrSubscriptionNotFound
384		}
385		if existing, ok := acc.bills[period]; ok {
386			return existing.bill, nil
387		}
388	
389		// 补齐到期安排（条件历史），随后按账期取该月当时适用的条件：
390		// 即使已经换过套餐或先出新月份账单再补旧月份账单，历史账单也不会被当前套餐覆盖。
391		s.applyDueChangesLocked(acc, s.nowUTC())
392	
393		activationMonth := MonthOf(acc.sub.activatedAt)
394		if period.Before(activationMonth) {
395			return Bill{}, ErrBillBeforeSubscription
396		}
397		now := s.nowUTC()
398		if !period.End().Before(now) && !period.End().Equal(now) {
399			return Bill{}, ErrBillMonthNotEnded
400		}
401	
402		terms := termsForPeriodLocked(acc.sub, period)
403		bill, err := buildBill(accountID, period, terms, acc.usage[period])
404		if err != nil {
405			return Bill{}, err
406		}
407		acc.bills[period] = &billRecord{bill: bill}
408		return bill, nil
409	}
410	
411	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
412	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
413		if accountID == "" {
414			return Bill{}, invalidf("account id is empty")
415		}
416		s.mu.Lock()
417		defer s.mu.Unlock()
418		acc, ok := s.accounts[accountID]
419		if !ok {
420			return Bill{}, ErrAccountNotFound
421		}
422		rec, ok := acc.bills[period]
423		if !ok {
424			return Bill{}, ErrBillNotFound
425		}
426		return rec.bill, nil
427	}
428	
429	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
430	// 付款标识在同一账户内去重：相同账单和金额的重报返回原结果，
431	// 改成其他账单或金额返回 ErrPaymentConflict；失败不消耗付款标识。
432	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
433		if accountID == "" {
434			return PaymentResult{}, invalidf("account id is empty")
435		}
436		if paymentID == "" {
437			return PaymentResult{}, invalidf("payment id is empty")
438		}
439		if amount <= 0 {
440			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
441		}
442		s.mu.Lock()
443		defer s.mu.Unlock()
444	
445		acc, ok := s.accounts[accountID]
446		if !ok {
447			return PaymentResult{}, ErrAccountNotFound
448		}
449		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
450		if prev, ok := acc.payments[paymentID]; ok {
451			if prev.period != period || prev.amount != amount {
452				return PaymentResult{}, ErrPaymentConflict
453			}
454			rec, ok := acc.bills[period]
455			if !ok {
456				return PaymentResult{}, ErrBillNotFound
457			}
458			return PaymentResult{
459				Registered:  false,
460				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
461				BillBalance: rec.bill.Balance,
462				Settled:     rec.bill.Settled,
463			}, nil
464		}
465	
466		rec, ok := acc.bills[period]
467		if !ok {
468			return PaymentResult{}, ErrBillNotFound
469		}
470	
471		if amount > rec.bill.Balance {
472			return PaymentResult{}, ErrPaymentExceedsBalance
473		}
474	
475		paid, ok := addNonNeg(rec.bill.Paid, amount)
476		if !ok {
477			return PaymentResult{}, ErrOverflow
478		}
479		rec.bill.Paid = paid
480		rec.bill.Balance -= amount
481		if rec.bill.Balance == 0 {
482			rec.bill.Settled = true
483		}
484		acc.payments[paymentID] = paymentRecord{period: period, amount: amount}
485	
486		return PaymentResult{
487			Registered:  true,
488			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
489			BillBalance: rec.bill.Balance,
490			Settled:     rec.bill.Settled,
491		}, nil
492	}
493	
494	// MonthlyUsage 返回账户某账期的累计用量；无任何用量时返回 0。
495	func (s *Service) MonthlyUsage(accountID string, period Month) (Usage, error) {
496		if accountID == "" {
497			return Usage{}, invalidf("account id is empty")
498		}
499		s.mu.Lock()
500		defer s.mu.Unlock()
501		acc, ok := s.accounts[accountID]
502		if !ok {
503			return Usage{}, ErrAccountNotFound
504		}
505		// 与其他入口保持一致：顺带让已到期的换套餐安排生效。
506		s.applyDueChangesLocked(acc, s.nowUTC())
507		return Usage{Period: period, Total: acc.usage[period]}, nil
508	}
509	
510	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
511	func (s *Service) Status(accountID string) (AccountStatus, error) {
512		if accountID == "" {
513			return AccountStatus{}, invalidf("account id is empty")
514		}
515		s.mu.Lock()
516		defer s.mu.Unlock()
517		acc, ok := s.accounts[accountID]
518		if !ok {
519			return AccountStatus{}, ErrAccountNotFound
520		}
521	
522		now := s.nowUTC()
523		// 查询即让已到期安排生效：月初零点之后无需上报用量或出账，当前条件立即更新。
524		s.applyDueChangesLocked(acc, now)
525	
526		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
527		for m := range acc.usage {
528			periodSet[m] = struct{}{}
529		}
530		for m := range acc.bills {
531			periodSet[m] = struct{}{}
532		}
533		periods := make([]Month, 0, len(periodSet))
534		for m := range periodSet {
535			periods = append(periods, m)
536		}
537		sortMonths(periods)
538	
539		st := AccountStatus{
540			AccountID:    accountID,
541			Subscribed:   acc.sub != nil,
542			Suspended:    s.isSuspendedLocked(acc, now),
543			MonthlyUsage: make([]Usage, 0, len(periods)),
544			Bills:        make([]BillSummary, 0, len(acc.bills)),
545		}
546		if acc.sub != nil {
547			st.CurrentTerms = acc.sub.terms
548			if acc.sub.pending != nil {
549				pending := *acc.sub.pending
550				st.PendingChange = &pending
551			}
552		}
553		for _, m := range periods {
554			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
555		}
556		for _, m := range periods {
557			if rec, ok := acc.bills[m]; ok {
558				b := rec.bill
559				st.Bills = append(st.Bills, BillSummary{
560					Period:   m,
561					TotalDue: b.TotalDue,
562					Paid:     b.Paid,
563					Balance:  b.Balance,
564					Settled:  b.Settled,
565					DueAt:    b.DueAt,
566				})
567			}
568		}
569		return st, nil
570	}
571	
572	// isSuspendedLocked 报告账户当前是否停用：
573	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
574	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
575		for _, rec := range acc.bills {
576			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
577				return true
578			}
579		}
580		return false
581	}
582	
583	func sortMonths(ms []Month) {
584		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
585	}
586	
587	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
588	func addNonNeg(a, b int64) (int64, bool) {
589		if a > maxInt64-b {
590			return 0, false
591		}
592		return a + b, true
593	}
594	
595	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
596	func mulNonNeg(a, b int64) (int64, bool) {
597		if a == 0 || b == 0 {
598			return 0, true
599		}
600		if a > maxInt64/b {
601			return 0, false
602		}
603		return a * b, true
604	}
605	
606	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
607	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
608		overageUnits := int64(0)
609		if totalUsage > t.IncludedUnits {
610			overageUnits = totalUsage - t.IncludedUnits
611		}
612		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
613		if !ok {
614			return Bill{}, ErrOverflow
615		}
616		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
617		if !ok {
618			return Bill{}, ErrOverflow
619		}
620		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
621		if !ok {
622			return Bill{}, ErrOverflow
623		}
624		totalDue, ok := addNonNeg(subtotal, tax)
625		if !ok {
626			return Bill{}, ErrOverflow
627		}
628		b := Bill{
629			AccountID:     accountID,
630			Period:        period,
631			Terms:         t,
632			TotalUsage:    totalUsage,
633			IncludedUnits: t.IncludedUnits,
634			OverageUnits:  overageUnits,
635			MonthlyFee:    t.MonthlyFee,
636			OverageFee:    overageFee,
637			Tax:           tax,
638			TotalDue:      totalDue,
639			Paid:          0,
640			Balance:       totalDue,
641			Settled:       totalDue == 0,
642			DueAt:         period.End().AddDate(0, 0, 7),
643		}
644		return b, nil
645	}
646	
647	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
648	// 拆分商和余数计算以避免乘积溢出 int64。
649	func rateAmount(amount, rate int64) (int64, bool) {
650		const den = 10000
651		q, r := amount/den, amount%den
652		qr, ok := mulNonNeg(q, rate)
653		if !ok {
654			return 0, false
655		}
656		rr, ok := mulNonNeg(r, rate)
657		if !ok {
658			return 0, false
659		}
660		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
661		add, ok := addNonNeg(qr, (rr+den/2)/den)
662		if !ok {
663			return 0, false
664		}
665		return add, true
666	}
