137	func TestEventDedupConflictAndTimeRules(t *testing.T) {
138		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
139		mustPlan(t, s, Plan{ID: "p", TaxRateBasisPoints: 0})
140		mustAccount(t, s, "a")
141		mustAccount(t, s, "b")
142	
143		ev := Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 14, 0, 0), Quantity: 3}
144		if _, err := s.RecordEvent(ev); !errors.Is(err, ErrSubscriptionNotFound) {
145			t.Fatalf("no sub: %v", err)
146		}
147		if err := s.Subscribe("a", "p", utc(2026, 1, 15, 8, 0)); err != nil {
148			t.Fatal(err)
149		}
150		if err := s.Subscribe("b", "p", utc(2026, 1, 15, 8, 0)); err != nil {
151			t.Fatal(err)
152		}
153	
154		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "x", At: utc(2026, 1, 15, 7, 59), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
155			t.Fatalf("before activation: %v", err)
156		}
157		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "x", At: clk.get().Add(time.Second), Quantity: 1}); !errors.Is(err, ErrEventInFuture) {
158			t.Fatalf("future: %v", err)
159		}
160		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "x", At: utc(2026, 1, 15, 9, 0), Quantity: -1}); !errors.Is(err, ErrInvalidArgument) {
161			t.Fatalf("negative qty: %v", err)
162		}
163		if _, err := s.RecordEvent(Event{AccountID: "ghost", EventID: "x", At: utc(2026, 1, 15, 9, 0), Quantity: 1}); !errors.Is(err, ErrAccountNotFound) {
164			t.Fatalf("missing account: %v", err)
165		}
166	
167		ev = Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 15, 9, 0), Quantity: 3}
168		r1, err := s.RecordEvent(ev)
169		if err != nil || !r1.Accepted || r1.Period != jan(2026) {
170			t.Fatalf("first accept: %+v %v", r1, err)
171		}
172		r2, err := s.RecordEvent(ev)
173		if err != nil || r2.Accepted {
174			t.Fatalf("identical replay must not accumulate: %+v %v", r2, err)
175		}
176		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: ev.At, Quantity: 4}); !errors.Is(err, ErrEventConflict) {
177			t.Fatalf("qty conflict: %v", err)
178		}
179		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: ev.At.Add(time.Second), Quantity: 3}); !errors.Is(err, ErrEventConflict) {
180			t.Fatalf("time conflict: %v", err)
181		}
182		// 冲突不改变累计用量。
183		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 3 {
184			t.Fatalf("usage after conflicts = %d", u.Total)
185		}
186	
187		// 不同账户可复用事件标识，且互不影响。
188		clk.t = utc(2026, 1, 16, 12, 0)
189		if _, err := s.RecordEvent(Event{AccountID: "b", EventID: "e1", At: utc(2026, 1, 16, 0, 0), Quantity: 7}); err != nil {
190			t.Fatalf("cross-account id: %v", err)
191		}
192		if u, _ := s.MonthlyUsage("b", jan(2026)); u.Total != 7 {
193			t.Fatalf("b usage = %d", u.Total)
194		}
195	
196		// 事件按发生时刻归账期：1 月 31 日深夜发生、2 月上报仍归入 1 月。
197		clk.t = utc(2026, 2, 1, 10, 0)
198		r3, err := s.RecordEvent(Event{AccountID: "a", EventID: "late", At: utc(2026, 1, 31, 23, 59), Quantity: 2})
199		if err != nil || r3.Period != jan(2026) {
200			t.Fatalf("late Jan event: %+v %v", r3, err)
201		}
202		// UTC 月初属于新一期。
203		r4, err := s.RecordEvent(Event{AccountID: "a", EventID: "feb1", At: utc(2026, 2, 1, 0, 0), Quantity: 4})
204		if err != nil || r4.Period != feb(2026) {
205			t.Fatalf("Feb boundary: %+v %v", r4, err)
206		}
207	
208		// 出账后：新事件拒绝，同标识重报仍成功。
209		bill, err := s.CreateBill("a", jan(2026))
210		if err != nil {
211			t.Fatal(err)
212		}
213		if bill.TotalUsage != 5 {
214			t.Fatalf("jan total = %d, want 5", bill.TotalUsage)
215		}
216		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "new-after-bill", At: utc(2026, 1, 20, 0, 0), Quantity: 1}); !errors.Is(err, ErrMonthBilled) {
217			t.Fatalf("new event after billed: %v", err)
218		}
219		if r, err := s.RecordEvent(ev); err != nil || r.Accepted {
220			t.Fatalf("replay after billed must succeed: %+v %v", r, err)
221		}
222	}
