224	func TestBillComputationFirstMonthFullTerms(t *testing.T) {
225		// 月费 10000 分，额度 10，单价 600 分，税率 10%（1000 万分点）。
226		s, clk := newTestService(utc(2026, 1, 22, 12, 0))
227		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 10000, IncludedUnits: 10, OveragePrice: 600, TaxRateBasisPoints: 1000})
228		mustAccount(t, s, "a")
229		if err := s.Subscribe("a", "p", utc(2026, 1, 15, 12, 0)); err != nil {
230			t.Fatal(err)
231		}
232		// 首月即用满 25：完整月费 + 完整额度。
233		for i, q := range []int64{10, 15} {
234			if _, err := s.RecordEvent(Event{AccountID: "a", EventID: fmt.Sprintf("e%d", i), At: utc(2026, 1, 20+i, 0, 0), Quantity: q}); err != nil {
235				t.Fatal(err)
236			}
237		}
238	
239		clk.t = utc(2026, 1, 31, 23, 59)
240		if _, err := s.CreateBill("a", jan(2026)); !errors.Is(err, ErrBillMonthNotEnded) {
241			t.Fatalf("open month: %v", err)
242		}
243		clk.t = utc(2026, 2, 1, 0, 0)
244		b, err := s.CreateBill("a", jan(2026))
245		if err != nil {
246			t.Fatal(err)
247		}
248		if b.TotalUsage != 25 || b.OverageUnits != 15 {
249			t.Fatalf("usage: total=%d over=%d", b.TotalUsage, b.OverageUnits)
250		}
251		if b.MonthlyFee != 10000 || b.OverageFee != 9000 {
252			t.Fatalf("fees: fee=%d over=%d", b.MonthlyFee, b.OverageFee)
253		}
254		// (10000+9000)*10% = 1900
255		if b.Tax != 1900 || b.TotalDue != 20900 || b.Balance != 20900 || b.Settled {
256			t.Fatalf("totals: tax=%d due=%d bal=%d settled=%v", b.Tax, b.TotalDue, b.Balance, b.Settled)
257		}
258		if !b.DueAt.Equal(utc(2026, 2, 8, 0, 0)) {
259			t.Fatalf("due at = %v", b.DueAt)
260		}
261		// 重复出账同一张，后续用量与付款状态变化不改金额（此处 1 月已出账，事件已被封）。
262		b2, err := s.CreateBill("a", jan(2026))
263		if err != nil || b2 != b {
264			t.Fatalf("bill not idempotent: %+v vs %+v err=%v", b, b2, err)
265		}
266	
267		// 开通当月之前不能出账。
268		if _, err := s.CreateBill("a", Month{Year: 2025, Month: time.December}); !errors.Is(err, ErrBillBeforeSubscription) {
269			t.Fatalf("before activation: %v", err)
270		}
271	
272		// 未用量月份也可出账：零用量、零超额。
273		clk.t = utc(2026, 3, 1, 0, 0)
274		febBill, err := s.CreateBill("a", feb(2026))
275		if err != nil {
276			t.Fatal(err)
277		}
278		if febBill.TotalUsage != 0 || febBill.OverageUnits != 0 || febBill.OverageFee != 0 {
279			t.Fatalf("empty month bill: %+v", febBill)
280		}
281	}
